42→  assert.match(validate(s, { ...good, score: 0.9 }).join("\n"), /field "score" is not allowed/);
43→});
44→
45→test("author confidence is null when not computable, never 0", () => {
46→  // 0 reads as "we measured it and the author is unreliable"; the truth is
47→  // "there is no data yet". Those must not collapse into the same value.
48→  const s = schema("gate-decision.schema.json");
49→  const pending = readJson(fixture("gate-decision.json"))[1];
50→  assert.equal(pending.signals.author.confidence, null);
51→  assert.equal(pending.signals.author.computable, false);
52→  assert.deepEqual(validate(s, pending), []);
53→});
54→
55→test("observation and evidence_tier are separate concepts", () => {
56→  // observation: how the fetch was witnessed. evidence_tier: how strong the
57→  // "it was used" judgement is. Values from one must not validate in the other.
58→  const s = schema("provenance-event.schema.json");
59→  const first = JSON.parse(readText(fixture("provenance-events.jsonl")).split("\n")[0]);
60→  assert.equal(first.observation, "bridge+wire");
61→  assert.equal(first.evidence_tier, null);
62→  assert.match(validate(s, { ...first, evidence_tier: "bridge+wire" }).join("\n"), /\.evidence_tier/);
63→});
64→
65→test("an unsupported keyword throws instead of silently passing", () => {
66→  // Silently ignoring it would make the contract look enforced while it is not.
67→  assert.throws(() => validate({ type: "object", oneOf: [] }, {}), /unsupported schema keyword "oneOf"/);
68→});
69→
70→test("type arrays admit null, and null inside enum still matches", () => {
71→  const s = { type: ["string", "null"], enum: ["a", null] };
72→  assert.deepEqual(validate(s, null), []);
73→  assert.deepEqual(validate(s, "a"), []);
74→  assert.match(validate(s, "b").join(), /must be one of/);
75→  assert.match(validate(s, 1).join(), /type must be/);
76→});
77→
78→test("errors carry a path that points at the nested field", () => {
79→  const s = schema("receipt.schema.json");
80→  const r = readJson(fixture("receipt.json"));
81→  r.items[1].status = "verified";
82→  const errs = validate(s, r);
83→  assert.equal(errs.length, 1);
84→  assert.match(errs[0], /^\$\.items\[1\]\.status/);
85→});
86→

freshness.description:
Filter search results by time range. Supports d[N], m[N], and y[N] for the last N calendar days, months, and years:
- d[N]: N is an integer from 1 to 30;
- m[N]: N is an integer from 1 to 12;
- y[N]: N is an integer from 1 to 5.

N may be omitted and defaults to 1. The current partial calendar unit counts as 1. For example, d1 means today, m1 means the current month to date, and y1 means the current year to date. Omit this parameter to disable time filtering.

