211→    // ".." 段防越界
212→    const segs = path.split(/[\\/]/);
213→    if (segs.some((s) => s === "..")) {
214→      throw new SkillResourceError("INVALID_PATH", `traversal not allowed: ${path}`);
215→    }
216→  }
