536→    path: string; content: string; encoding: "utf-8" | "base64";
537→    size_bytes: number; mime_type: string; version: number;
538→  }> {
539→    const head = await this.store.getHead(input.skill_id, input.team_id);
540→    if (input.team_id) assertTeamMatchWrap(head, input.team_id);
541→    if (!head) throw new SkillCoreError("SKILL_NOT_FOUND");
542→    const ver = input.version ?? head.version;
543→    // 校验 path 是否在该版本的 manifest 中（如果是 head 直接看 head.manifest，否则查 by version）
544→    const target = typeof input.version === "number" && input.version !== head.version
545→      ? await this.store.getByVersion(input.skill_id, input.version, input.team_id)
546→      : head;
547→    if (!target) {
548→      // head 存在但指定版本查不到 → 版本已被 GC，不是 skill 不存在
549→      throw new SkillCoreError(
550→        "STORAGE_NOT_FOUND",
551→        `version ${input.version} not found (may have been GC'd); current head is v${head.version}`,
552→      );
553→    }
554→    // TTL 检查：指定旧版本资源时拦截
555→    if (typeof input.version === "number" && input.version !== head.version) {
556→      this.assertVersionNotExpired(target, head.version);
557→    }
558→    const exists = target.manifest.some((m) => m.path === input.path);
559→    if (!exists) throw new SkillCoreError("SKILL_NOT_FOUND", `path ${input.path} not in manifest of v${ver}`);
560→
561→    const r = await this.resources.readResource(input.skill_id, ver, input.path, input.encoding ?? "utf-8");
562→    if (!r) throw new SkillCoreError("STORAGE_NOT_FOUND", "version directory missing (may be GC'd)");
563→    this.notifyAccessed(head);
564→    return {
565→      path: r.path,
566→      content: r.content,
567→      encoding: r.encoding,
568→      size_bytes: r.size_bytes,
569→      mime_type: r.mime_type,
570→      version: ver,
571→    };
572→  }
