205→  private assertPath(path: string): void {
206→    if (!path) throw new SkillResourceError("INVALID_PATH", "empty path");
207→    if (path.startsWith("/") || path.startsWith("\\"))
208→      throw new SkillResourceError("INVALID_PATH", `absolute path not allowed: ${path}`);
209→    if (path.includes("\0"))
210→      throw new SkillResourceError("INVALID_PATH", `NUL not allowed: ${path}`);
211→    // ".." 段防越界
212→    const segs = path.split(/[\\/]/);
213→    if (segs.some((s) => s === "..")) {
214→      throw new SkillResourceError("INVALID_PATH", `traversal not allowed: ${path}`);
